/* ==========================================================================
   BANCO DE EXERCÍCIOS — Metodologia Da Base ao Topo · Academia JV Tênis
   --------------------------------------------------------------------------
   Este arquivo é O BANCO. Só dados, nenhuma tela: o `index.html` lê daqui.
   Para acrescentar exercício, copie um bloco existente e preencha os campos.
   Nada precisa ser recompilado — salvar o arquivo já basta.

   CAMPOS DE CADA EXERCÍCIO
   id        código curto, único (aparece na ficha e no plano de aula)
   nome      o nome usado em quadra (vocabulário compartilhado encurta instrução)
   tema      em que tema(s) do mês ele entra  → ver TEMAS
   camada    camada da Pirâmide (1 a 6)       → ver CAMADAS
   bloco     onde entra na aula               → ver BLOCOS
   niveis    níveis da Trilha que aproveitam  → ver NIVEIS
   min       duração sugerida em minutos
   int       intensidade física: baixa | media | alta
   objetivo  o PARA QUÊ. Se o professor não souber dizer, não aplique.
   montagem  o que colocar na quadra antes de começar
   execucao  como roda, passo a passo
   prog      o MESMO exercício em cada nível (a espiral da metodologia)
   erro      o erro a observar PRIMEIRO — e sempre o mais baixo da cadeia
   sucesso   critério objetivo: como saber que funcionou (número, não opinião)
   mat       materiais                         → ver MATERIAIS
   form      formatos de aula que comportam    → ver FORMATOS
   nec       necessidades específicas do aluno → ver NECESSIDADES
   kids      (opcional) como virar brincadeira para criança
   fonte     'apostila' = está na apostila oficial · 'banco' = ampliação
   ========================================================================== */

