  execucao:`Troca viva. Depois de cada bola do aluno, ele tem que recuperar para o cone CERTO conforme a direção que acabou de bater: bateu cruzado, espera mais de um lado; bateu paralelo, espera do outro. O professor confere e explica a primeira vez, depois só aponta.`,
  prog:{ construcao:`Só duas opções de cone.`,
         ascensao:`Três cones, sem aviso.`,
         topo:`Sem cones: o aluno justifica cada espera em voz alta.` },
  erro:`Voltar sempre ao centro geométrico (o erro mais comum do aluno organizado).`,
  sucesso:`Acerta o cone em 8 de 10 bolas.`,
