  montagem:`Alvo grande no canto do backhand do adversário. Cesta.`,
  execucao:`Bola lançada no meio ou na metade do backhand do aluno. Ele CONTORNA a bola com passo lateral (nunca correndo de lado sem se posicionar), bate de forehand em base aberta e manda inside-out no alvo. Recupera imediatamente, porque acabou de abandonar meia quadra.`,
