  montagem:`Mini-quadra ou quadra reduzida; bola adaptada.`,
  execucao:`Pontos valendo em que o ponto vale DOBRADO se quem ganhou estava na frente da linha de saque. O professor narra o placar em voz alta — o incentivo faz o aluno querer ir para frente.`,
