/* ==========================================================================
   FUNÇÕES DE APOIO — usadas pela tela. Nada de dados aqui.
   ========================================================================== */

/* Tema do mês de hoje (ou de um mês qualquer, 1 a 12). */
function temaDoMes(mes){
  const m = mes || (new Date().getMonth() + 1);
  return TEMAS.find(t => t.meses.indexOf(m) >= 0) || TEMAS[0];
}

function tema(id){    return TEMAS.find(t => t.id === id); }
function nivel(id){   return NIVEIS.find(n => n.id === id); }
function bloco(id){   return BLOCOS.find(b => b.id === id); }
function camada(n){   return CAMADAS.find(c => c.n === n); }
function formato(id){ return FORMATOS.find(f => f.id === id); }
function material(id){return MATERIAIS.find(m => m.id === id); }
function necessidade(id){ return NECESSIDADES.find(x => x.id === id); }

const MESES_NOME = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho',
                    'Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
